Function valor <- PriceOf(codigo As Integer)
  Define valor As Integer;
  Switch codigo Do
    1:
      valor <- 3;
    2:
      valor <- 5;
    3:
      valor <- 2;
    4:
      valor <- 1;
    Otherwise:
      valor <- 2;
  EndSwitch
EndFunction

Function amount <- Line(price As Integer, quantity As Integer)
  Define amount As Integer;
  amount <- price * quantity;
EndFunction

Function discounted <- WithDiscount(total As Integer)
  Define discounted As Integer;
  discounted <- total - total Div 10;
EndFunction

Algorithm Receipt
  Define code1, quantity1, code2, quantity2 As Integer;
  Read code1;
  Read quantity1;
  Read code2;
  Read quantity2;
  Write WithDiscount(Line(PriceOf(code1), quantity1) + Line(PriceOf(code2), quantity2));
EndAlgorithm
